// Built-in place list (works offline): every Telangana and Andhra Pradesh district headquarters,
// major towns in every Indian state, and cities worldwide with Telugu/Indian communities.
// Generated by scripts/build-places.mjs from GeoNames data (CC BY 4.0). Any other town or
// village is found online through searchPlaces() in geocode.ts.
import type { Place } from '../engine/panchang';
import RAW from './places-builtin.json';

interface Raw { n: string; a: string; c: string; cc: string; lat: number; lon: number; tz: string; p: number }

export const US_STATES: Record<string, string> = {
  Alabama: 'AL', Alaska: 'AK', Arizona: 'AZ', Arkansas: 'AR', California: 'CA', Colorado: 'CO', Connecticut: 'CT', Delaware: 'DE',
  'District of Columbia': 'DC', Florida: 'FL', Georgia: 'GA', Hawaii: 'HI', Idaho: 'ID', Illinois: 'IL', Indiana: 'IN', Iowa: 'IA',
  Kansas: 'KS', Kentucky: 'KY', Louisiana: 'LA', Maine: 'ME', Maryland: 'MD', Massachusetts: 'MA', Michigan: 'MI', Minnesota: 'MN',
  Mississippi: 'MS', Missouri: 'MO', Montana: 'MT', Nebraska: 'NE', Nevada: 'NV', 'New Hampshire': 'NH', 'New Jersey': 'NJ',
  'New Mexico': 'NM', 'New York': 'NY', 'North Carolina': 'NC', 'North Dakota': 'ND', Ohio: 'OH', Oklahoma: 'OK', Oregon: 'OR',
  Pennsylvania: 'PA', 'Rhode Island': 'RI', 'South Carolina': 'SC', 'South Dakota': 'SD', Tennessee: 'TN', Texas: 'TX', Utah: 'UT',
  Vermont: 'VT', Virginia: 'VA', Washington: 'WA', 'West Virginia': 'WV', Wisconsin: 'WI', Wyoming: 'WY',
};
export const CA_PROVINCES: Record<string, string> = {
  Ontario: 'ON', Quebec: 'QC', 'British Columbia': 'BC', Alberta: 'AB', Manitoba: 'MB', Saskatchewan: 'SK',
  'Nova Scotia': 'NS', 'New Brunswick': 'NB', 'Newfoundland and Labrador': 'NL', 'Prince Edward Island': 'PE',
};
/** Common abbreviations people type for Indian states. */
const IN_STATE_ABBR: Record<string, string[]> = {
  'Andhra Pradesh': ['ap'], Telangana: ['ts', 'tg'], Karnataka: ['ka'], 'Tamil Nadu': ['tn'], Kerala: ['kl'], Maharashtra: ['mh'],
  Gujarat: ['gj'], Rajasthan: ['rj'], 'Uttar Pradesh': ['up'], 'Madhya Pradesh': ['mp'], 'West Bengal': ['wb'], Odisha: ['od', 'or'],
  Bihar: ['br'], Delhi: ['dl'], Punjab: ['pb'], Haryana: ['hr'], Uttarakhand: ['uk'], 'Himachal Pradesh': ['hp'], Chhattisgarh: ['cg'],
};
/** Older or alternate spellings → current name, so either finds the place. */
const ALIASES: Record<string, string[]> = {
  Mumbai: ['bombay'], Chennai: ['madras'], Kolkata: ['calcutta'], Bengaluru: ['bangalore'], Mysuru: ['mysore'], Mangaluru: ['mangalore'],
  Hubballi: ['hubli'], Belagavi: ['belgaum'], Ballari: ['bellary'], Tumakuru: ['tumkur'], Kalaburagi: ['gulbarga'], Shivamogga: ['shimoga'],
  Gurugram: ['gurgaon'], Visakhapatnam: ['vizag', 'vishakhapatnam', 'waltair'], Rajahmundry: ['rajamahendravaram', 'rajamundry'],
  Vadodara: ['baroda'], Thiruvananthapuram: ['trivandrum'], Kochi: ['cochin', 'ernakulam'], Kozhikode: ['calicut'], Pune: ['poona'],
  Varanasi: ['benares', 'banaras', 'kashi'], Prayagraj: ['allahabad'], Puducherry: ['pondicherry'], Panaji: ['panjim'], Margao: ['madgaon'],
  Kothagudem: ['kottagudem'], Hanamkonda: ['hanumakonda'], Kanyakumari: ['kanniyakumari'], Tenali: ['thenali'], Suryapet: ['suriapet'],
  Wanaparthy: ['wanparti'], Kadapa: ['cuddapah'], Anantapur: ['anantapuram'], Nellore: ['sri potti sriramulu nellore'], Tiruchirappalli: ['trichy'],
  Bhongir: ['bhuvanagiri', 'yadadri'], Basar: ['basara'], Aurangabad: ['chhatrapati sambhajinagar'], Mahbubnagar: ['mahabubnagar', 'palamuru'],
  'New Delhi': ['delhi'], 'New York': ['nyc', 'manhattan'], 'Washington': ['dc'], 'Kuwait City': ['kuwait'], 'Ho Chi Minh City': ['saigon'],
};

export const fold = (s: string) => s.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();

/** Display label: "Guntur, Andhra Pradesh", "Edison, NJ", "Toronto, ON", "London, United Kingdom". */
export function placeLabel(name: string, region: string | undefined, country: string | undefined, cc: string | undefined): string {
  if (cc === 'US' && region && US_STATES[region]) return name === 'Washington' && region === 'District of Columbia' ? 'Washington, DC' : `${name}, ${US_STATES[region]}`;
  if (cc === 'CA' && region && CA_PROVINCES[region]) return `${name}, ${CA_PROVINCES[region]}`;
  if (cc === 'IN') return region && region !== name ? `${name}, ${region}` : name;
  if (!country || country === name || ['SG', 'HK'].includes(cc ?? '')) return name;
  return `${name}, ${country}`;
}

export interface PlaceEntry extends Place {
  region: string;
  country: string;
  cc: string;
  population: number;
  /** Folded search keys: name, aliases. */
  keys: string[];
  /** Folded qualifiers: state, abbreviations, country. */
  quals: string[];
}

export const PLACES: PlaceEntry[] = (RAW as Raw[]).map((r) => ({
  name: placeLabel(r.n, r.a, r.c, r.cc), lat: r.lat, lon: r.lon, tz: r.tz,
  region: r.a, country: r.c, cc: r.cc, population: r.p,
  keys: [fold(r.n), ...(ALIASES[r.n] ?? [])],
  quals: [fold(r.a), ...(IN_STATE_ABBR[r.a] ?? []), ...(US_STATES[r.a] ? [US_STATES[r.a].toLowerCase()] : []), ...(CA_PROVINCES[r.a] ? [CA_PROVINCES[r.a].toLowerCase()] : []), fold(r.c), r.cc.toLowerCase(), ...(r.cc === 'US' ? ['usa', 'us', 'america'] : r.cc === 'GB' ? ['uk', 'england', 'britain'] : r.cc === 'AE' ? ['uae'] : [])],
})).sort((a, b) => Number(b.cc === 'IN') - Number(a.cc === 'IN') || b.population - a.population);

export const findPlace = (name: string) => PLACES.find((p) => p.name === name || p.name.startsWith(`${name},`));

/**
 * Offline search. "gun" → Guntur…, "guntur ap", "edison nj", "london uk", "vizag" all work.
 * The first word(s) match the town (or an old name); later words narrow by state or country.
 */
export function searchLocal(query: string, limit = 8): PlaceEntry[] {
  const q = fold(query.replace(/,/g, ' '));
  if (!q) return [];
  const words = q.split(' ');
  const scored: Array<{ p: PlaceEntry; s: number }> = [];
  for (const p of PLACES) {
    let best = -1;
    // Try splitting the query into "town words" + "qualifier words".
    for (let k = words.length; k >= 1; k--) {
      const town = words.slice(0, k).join(' ');
      const rest = words.slice(k);
      const key = p.keys.find((x) => x.startsWith(town));
      if (!key) continue;
      if (!rest.every((w) => p.quals.some((x) => x.startsWith(w) || x.split(' ').some((y) => y.startsWith(w))))) continue;
      best = (key === town ? 3 : 2) + (key === p.keys[0] ? 0.5 : 0);
      break;
    }
    if (best < 0 && words.length === 1 && q.length >= 3 && p.quals.slice(0, 1).some((x) => x.startsWith(q))) best = 0.5; // a state name lists its towns
    if (best >= 0) scored.push({ p, s: best + Math.log10(p.population + 10) / 10 });
  }
  return scored.sort((a, b) => b.s - a.s).slice(0, limit).map((x) => x.p);
}

/** Suggestions shown before the user types. */
export const POPULAR = ['Hyderabad', 'Vijayawada', 'Visakhapatnam', 'Tirupati', 'Warangal', 'Guntur', 'Bengaluru', 'Chennai', 'Edison', 'Dallas', 'San Jose', 'London']
  .map((n) => PLACES.find((p) => p.keys[0] === fold(n))!).filter(Boolean);

export function placeKey(p: Place): string {
  return `${p.lat.toFixed(3)},${p.lon.toFixed(3)},${p.tz}`;
}
